#pragma warning disable CA1707
using FluentValidation.TestHelper;using WhatsBiz.Application.Features.Purchases;
namespace WhatsBiz.Tests.Purchases;
public sealed class PurchaseValidatorTests{private readonly PurchaseInputValidator validator=new();[Fact]public void Requires_supplier_warehouse_and_items(){var input=new PurchaseInput(Guid.Empty,null,DateTimeOffset.UtcNow,null,Guid.Empty,[],[],[],0,0,null,"POSTED");var result=validator.TestValidate(input);result.ShouldHaveValidationErrorFor(x=>x.SupplierId);result.ShouldHaveValidationErrorFor(x=>x.WarehouseId);result.ShouldHaveValidationErrorFor(x=>x.Items);}[Fact]public void Rejects_invalid_quantity_and_mrp(){var item=new PurchaseItemInput(Guid.NewGuid(),null,null,null,0,0,10,9,10,0,0,18);var input=new PurchaseInput(Guid.NewGuid(),null,DateTimeOffset.UtcNow,null,Guid.NewGuid(),[item],[],[],0,0,null,"POSTED");var result=validator.TestValidate(input);result.ShouldHaveAnyValidationError();}[Fact]public void Accepts_valid_purchase(){var item=new PurchaseItemInput(Guid.NewGuid(),null,"B1",DateOnly.FromDateTime(DateTime.Today.AddMonths(6)),2,1,100,140,120,5,0,18);var input=new PurchaseInput(Guid.NewGuid(),"S-1",DateTimeOffset.UtcNow,null,Guid.NewGuid(),[item],[],[],0,0,null,"POSTED");validator.TestValidate(input).ShouldNotHaveAnyValidationErrors();}}
